public function log(array $events): void
{
    $this->connection->transactional(function (Connection $c) use ($events): void {
        // only for this transaction; for data that is not critical
        $c->executeStatement('SET LOCAL synchronous_commit = off');

        foreach ($events as $e) {
            $c->insert('click_event', ['page' => $e['page'], 'at' => $e['at']]);
        }
    });
}

foreach ($events as $e) {
    // autocommit: every insert is its own transaction and its own flush
    $this->connection->insert('click_event', ['page' => $e['page'], 'at' => $e['at']]);
}

// one transaction per chunk: one flush for every 1,000 rows
foreach (array_chunk($events, 1000) as $chunk) {
    $this->connection->transactional(function (Connection $c) use ($chunk): void {
        foreach ($chunk as $e) {
            $c->insert('click_event', ['page' => $e['page'], 'at' => $e['at']]);
        }
    });
}

