#[AsEventListener(event: KernelEvents::REQUEST)]
final readonly class StickyPrimaryListener
{
    public function __construct(private Connection $connection) {}

    public function __invoke(RequestEvent $event): void
    {
        $request = $event->getRequest();
        if (!$event->isMainRequest() || !$request->hasSession()) {
            return;
        }

        $until = $request->getSession()->get('primary_until', 0);
        if ($until > time() && $this->connection instanceof PrimaryReadReplicaConnection) {
            $this->connection->ensureConnectedToPrimary();   // primary until that time
        }
    }
}

