final readonly class ShardRouter
{
    private const BUCKETS = 1024;

    /** @param array<int, string> $bucketToShard bucket -> 'shard_0' */
    public function __construct(
        private ManagerRegistry $registry,
        private array $bucketToShard,
    ) {}

    public function connectionFor(int $customerId): Connection
    {
        $bucket = crc32((string) $customerId) % self::BUCKETS;

        return $this->registry->getConnection($this->bucketToShard[$bucket]);
    }
}

