final readonly class FreshReadGuard
{
    public function __construct(
        #[Autowire(service: 'doctrine.dbal.default_connection')]
        private PrimaryReadReplicaConnection $db,
    ) {}

    public function rememberWrite(SessionInterface $session): void
    {
        $this->db->ensureConnectedToPrimary();
        $session->set('min_lsn', $this->db->fetchOne('SELECT pg_current_wal_lsn()'));
    }

    public function usePrimaryIfReplicaBehind(SessionInterface $session): void
    {
        $min = $session->get('min_lsn');
        if ($min === null) {
            return;
        }

        $this->db->ensureConnectedToReplica();
        $fresh = $this->db->fetchOne(
            'SELECT pg_last_wal_replay_lsn() >= CAST(? AS pg_lsn)', [$min],
        );
        if (!$fresh) {
            $this->db->ensureConnectedToPrimary();
        }
    }
}

final readonly class CausalReplies
{
    public function __construct(
        private Connection $questionPrimary,
        private Connection $questionReplica,
        private Connection $answerDb,
    ) {}

    public function reply(int $questionId, string $text): void
    {
        $this->answerDb->insert('reply', [
            'question_id' => $questionId,
            'text' => $text,
            // a position that already contains the question
            'cause_lsn' => $this->questionPrimary->fetchOne('SELECT pg_current_wal_lsn()'),
        ]);
    }

    public function questionFor(array $reply): array|false
    {
        $caughtUp = $this->questionReplica->fetchOne(
            'SELECT pg_last_wal_replay_lsn() >= CAST(? AS pg_lsn)', [$reply['cause_lsn']],
        );
        $db = $caughtUp ? $this->questionReplica : $this->questionPrimary;

        return $db->fetchAssociative(
            'SELECT * FROM question WHERE id = ?', [$reply['question_id']],
        );
    }
}

