/** @return list<Order> with customers and items, in 2 queries */
public function findLatestWithItems(int $limit = 50): array
{
    // query 1: orders + customers (to-one, so LIMIT is safe)
    $orders = $this->createQueryBuilder('o')
        ->addSelect('c')
        ->join('o.customer', 'c')
        ->orderBy('o.createdAt', 'DESC')
        ->setMaxResults($limit)
        ->getQuery()
        ->getResult();

    // query 2: all items and products for these orders at once
    $ids = array_map(static fn (Order $o): int => $o->getId(), $orders);
    $this->createQueryBuilder('o')
        ->addSelect('i', 'p')
        ->leftJoin('o.items', 'i')
        ->leftJoin('i.product', 'p')
        ->where('o.id IN (:ids)')
        ->setParameter('ids', $ids)
        ->getQuery()
        ->getResult();

    return $orders;
}

