final readonly class AvatarStorage
{
    public function __construct(private FilesystemOperator $uploadsStorage) {}

    public function store(UploadedFile $file): string
    {
        $key = sprintf('avatars/%s.%s', Uuid::v7(), $file->guessExtension());

        $stream = fopen($file->getPathname(), 'rb');
        $this->uploadsStorage->writeStream($key, $stream);   // stream, not all in RAM
