        'url' => $post->getFormAttributes()['action'],
        'fields' => $post->getFormInputs(),
    ]);
}

final readonly class UploadLifecycle
{
    public function __construct(
        private S3Client $s3,
        private PendingUploadRepository $pending,
        private string $bucket,
    ) {}

    public function confirm(PendingUpload $up): void
    {
        $head = $this->s3->headObject(['Bucket' => $this->bucket, 'Key' => $up->key]);
        $tooBig = $head['ContentLength'] > 5 * 1024 * 1024;
        if ($tooBig || $head['ContentType'] !== 'image/jpeg') {
            $this->discard($up);
            throw new BadRequestHttpException('Upload rejected.');
        }
        $up->markUploaded();   // only now may the key go into the user's profile
    }

    #[AsMessageHandler]
    public function cleanUp(CleanUpPendingUploads $m): void
    {
        foreach ($this->pending->olderThan(new \DateTimeImmutable('-1 hour')) as $up) {
            $this->discard($up);
        }
    }

    private function discard(PendingUpload $up): void
    {
        $this->s3->deleteObject(['Bucket' => $this->bucket, 'Key' => $up->key]);
        $this->pending->remove($up);   // deleting a missing object is not an error
    }
}

public function start(string $key): string
{
    return $this->s3->createMultipartUpload([
        'Bucket' => $this->bucket, 'Key' => $key,
    ])['UploadId'];
}

public function partUrl(string $key, string $uploadId, int $part): string
{
    $cmd = $this->s3->getCommand('UploadPart', [
        'Bucket' => $this->bucket, 'Key' => $key,
        'UploadId' => $uploadId, 'PartNumber' => $part,
    ]);
    return (string) $this->s3->createPresignedRequest($cmd, '+1 hour')->getUri();
}

/** @param list<array{PartNumber:int, ETag:string}> $parts */
public function finish(string $key, string $uploadId, array $parts): void
{
    $this->s3->completeMultipartUpload([
        'Bucket' => $this->bucket, 'Key' => $key, 'UploadId' => $uploadId,
        'MultipartUpload' => ['Parts' => $parts],
    ]);
}

/** @return list<array{PartNumber:int, ETag:string}> */
public function uploadedParts(string $key, string $uploadId): array
{
    $parts = [];
    $pages = $this->s3->getPaginator('ListParts', [
        'Bucket' => $this->bucket, 'Key' => $key, 'UploadId' => $uploadId,
    ]);
    foreach ($pages as $page) {
        foreach ($page['Parts'] ?? [] as $p) {
            $parts[] = ['PartNumber' => $p['PartNumber'], 'ETag' => $p['ETag']];
        }
    }
    return $parts;
}

public function complete(string $key, string $uploadId, int $expected): void
{
    $parts = $this->uploadedParts($key, $uploadId);   // storage's list, not the client's
    if (count($parts) !== $expected) {
        throw new \DomainException('Some parts are still missing.');
    }
    $this->finish($key, $uploadId, $parts);
}

const PART = 5 * 1024 * 1024   // 5 MB per part
const call = (url: string, init?: RequestInit) => fetch(url, init).then((r) => r.json())

export async function upload(file: File) {
  const id = `upload:${file.name}:${file.size}:${file.lastModified}`
  let up = JSON.parse(localStorage.getItem(id) ?? 'null')
  if (!up) {
    up = await call('/uploads/multipart', { method: 'POST' })   // { key, uploadId }
    localStorage.setItem(id, JSON.stringify(up))
  }
  const base = `/uploads/multipart/${up.uploadId}`
  const have = new Set<number>(await call(`${base}/parts`))   // part numbers storage holds
  const total = Math.ceil(file.size / PART)

  for (let n = 1; n <= total; n++) {
    if (have.has(n)) continue   // already stored: skip
    const { url } = await call(`${base}/part-url/${n}`)
    const res = await fetch(url, { method: 'PUT', body: file.slice((n - 1) * PART, n * PART) })
    if (!res.ok) throw new Error(`part ${n} failed`)   // call upload() again to resume
  }
  await call(`${base}/complete`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ total }),
  })
  localStorage.removeItem(id)
}

