#[AsCommand(name: 'app:backfill-mobile')]
final class BackfillMobileCommand extends Command
{
    public function __construct(private readonly Connection $db)
    {
        parent::__construct();
    }

    protected function execute(InputInterface $in, OutputInterface $out): int
    {
        $lastId = 0;
        while (true) {
            $ids = $this->db->fetchFirstColumn(
                'SELECT id FROM users WHERE id > ? AND mobile_number IS NULL
                 AND phone IS NOT NULL ORDER BY id LIMIT 1000',
                [$lastId],
            );
            if ($ids === []) {
                return Command::SUCCESS;
            }
            $this->db->executeStatement(
                'UPDATE users SET mobile_number = phone WHERE id IN (?)',
                [$ids], [ArrayParameterType::INTEGER],
            );
            $lastId = (int) end($ids);
            $out->writeln("done up to id $lastId");
            usleep(100_000);   // let the replica and the database catch their breath
        }
    }
}

