  ADD CONSTRAINT users_mobile_nn CHECK (mobile_number IS NOT NULL) NOT VALID;

-- step 2: check the existing rows while writes carry on
ALTER TABLE users VALIDATE CONSTRAINT users_mobile_nn;

-- step 3 (PostgreSQL 12+): the proof exists, so NOT NULL needs no scan
