public function change(Product $p, int $newPrice, User $by): void
{
    $this->em->wrapInTransaction(function () use ($p, $newPrice, $by): void {
        $old = $p->getPrice();
        $p->setPrice($newPrice);

        $this->db->insert('audit_log', [
            'actor_id'    => $by->getId(),
            'entity_type' => 'product',
            'entity_id'   => $p->getId(),
            'action'      => 'updated',
            'old_values'  => json_encode(['price' => $old]),
            'new_values'  => json_encode(['price' => $newPrice]),
        ]);
    });
}

public function setPrice(int $productId, int $amount, \DateTimeImmutable $from): void
{
    $this->em->wrapInTransaction(function () use ($productId, $amount, $from): void {
        // close the current price at the moment the new one starts
        $this->db->executeStatement(
            'UPDATE product_prices SET valid_to = :from
             WHERE product_id = :p AND valid_to IS NULL',
            ['from' => $from, 'p' => $productId],
            ['from' => Types::DATETIMETZ_IMMUTABLE],
        );
        $this->db->insert('product_prices', [
            'product_id' => $productId, 'amount' => $amount,
            'valid_from' => $from->format('c'),
        ]);
    });
}

