    public function getSchedule(): Schedule
    {
        return (new Schedule())->add(
            RecurringMessage::cron('30 3 * * *', new PurgeLoginEvents()),
        );
    }
}

#[AsMessageHandler]
final readonly class PurgeLoginEventsHandler
{
    public function __construct(
        private Connection $db,
        private ClockInterface $clock,
        #[Autowire('%app.retention.login_events_days%')] private int $days,
    ) {}

    public function __invoke(PurgeLoginEvents $m): void
    {
        $cutoff = $this->clock->now()->modify("-{$this->days} days");
        do {
            $deleted = $this->db->executeStatement(
                'DELETE FROM login_events WHERE id IN (
                     SELECT id FROM login_events WHERE created_at < :c LIMIT 5000)',
                ['c' => $cutoff], ['c' => Types::DATETIMETZ_IMMUTABLE],
            );
        } while ($deleted === 5000);
    }
}

public function erase(User $user): void
{
    $id = $user->getId();

    $this->em->wrapInTransaction(function () use ($user): void {
        $user->anonymize();            // personal data becomes meaningless values
        $this->sessions->revokeAll($user);
    });

    // a separate database: restoring the main one cannot roll this list back
    $this->erasureDb->insert('erasure_log', [
        'user_id' => $id,
        'erased_at' => (new \DateTimeImmutable())->format('c'),
    ]);

    // after the commit, tell everyone: search, analytics, cache
    $this->bus->dispatch(new UserErased($id));
}

