protected function execute(InputInterface $in, OutputInterface $out): int
{
    $since = $this->db->fetchOne(
        "SELECT value FROM etl_watermark WHERE name = 'orders'"
    );
    $rows = $this->replica->iterateAssociative(
        'SELECT id, user_id, total_amount, status, created_at, updated_at FROM orders
         WHERE updated_at >= :s ORDER BY updated_at',
        ['s' => $since],
    );

    $stream = fopen('php://temp', 'w+b');
    foreach ($rows as $row) {
        fwrite($stream, json_encode($row, JSON_THROW_ON_ERROR)."\n");
        $max = $row['updated_at'];
    }
    rewind($stream);

    $key = sprintf('raw/orders/dt=%s/%s.jsonl', date('Y-m-d'), Uuid::v7());
    $this->lakeStorage->writeStream($key, $stream);   // E: the file lands in the lake

    $uri = 'gs://shop-lake/'.$key;
    $this->warehouse->runQuery($this->warehouse->query(   // L: the warehouse loads it
        "LOAD DATA INTO raw.raw_orders FROM FILES (format = 'JSON', uris = ['$uri'])",
    ));
    $this->db->executeStatement(
        "UPDATE etl_watermark SET value = :v WHERE name = 'orders'",
        ['v' => $max ?? $since],
    );

    return Command::SUCCESS;
}
